    const manhourRecords=periodRecords.filter(r=>r.module==='manhours'),trainingRecords=periodRecords.filter(r=>['training','tbt'].includes(r.module)),accidentRecords=periodRecords.filter(r=>r.module==='accidents'),nearRecords=periodRecords.filter(r=>r.module==='near_miss'),manhours=manhourRecords.reduce((a,r)=>a+Number(r.data?.hours||0),0),participantHours=trainingRecords.reduce((a,r)=>a+Number(r.data?.participant_hours||0),0),compliance=complianceAlertSummary();
