    const rawEventDate=out.event_date||extra.inspection_date||extra.training_date||extra.issue_date||extra.joining_date||extra.date||'';
    const parsedEventDate=normalizeImportDate(rawEventDate);const eventDate=rawEventDate?parsedEventDate:(importDraft.useTodayForBlankDates?today():'');const location=out.location||'';const department=out.department||state.membership?.department||state.profile?.department||'';
