    document.getElementById('import-allow-duplicates')?.addEventListener('change',e=>{importDraft.duplicateOverride=e.target.checked});
    document.getElementById('import-use-today')?.addEventListener('change',e=>{importDraft.useTodayForBlankDates=e.target.checked;renderImportPreview()});
