  function wireCompetencyPurposeUI(modal){
    if(!modal)return;const purpose=modal.querySelector('#f_record_purpose');if(!purpose)return;
    const evidenceOnly=['employee_code','employee_name','designation','provider','issue_date','expiry_date','renewal_status','proof_reference','verified_by','verification_date','remarks'];
    const requirementOnly=['required_for_designation','required_for_department','required_for_employment_type','requirement_strength','refresh_interval_months','requirement_notes'];
    const sync=(clearOppositeFields=false)=>{const requirement=purpose.value==='Role Requirement';for(const id of evidenceOnly){const field=modal.querySelector(`[data-field-id="${id}"]`);if(field)field.hidden=requirement}for(const id of requirementOnly){const field=modal.querySelector(`[data-field-id="${id}"]`);if(field)field.hidden=!requirement}const employeeCode=modal.querySelector('#f_course_code');if(employeeCode){const wrap=employeeCode.closest('[data-field-id]');if(wrap)wrap.hidden=false}const summary=modal.querySelector('#f_summary');if(summary&&(!summary.value.trim()||summary.value.includes('Competency record'))&&requirement){summary.value=modal.querySelector('#f_certificate')?.value?.trim()||'Role training requirement';summary.dataset.autoCourseName='1'}if(clearOppositeFields){const toClear=requirement?evidenceOnly:requirementOnly;for(const id of toClear){const el=modal.querySelector(`#f_${id}`);if(el){if(el.tagName==='SELECT')el.selectedIndex=-1;else el.value=''}}if(modal.dataset.localDraftKey)saveLocalDraftSnapshot(modal,modal.dataset.localDraftKey)}};
    purpose.addEventListener('change',()=>{sync(true);if(modal.dataset.localDraftKey)saveLocalDraftSnapshot(modal,modal.dataset.localDraftKey)});modal.querySelector('[data-local-draft-restore]')?.addEventListener('click',()=>queueMicrotask(()=>sync(false)));modal.querySelector('#f_certificate')?.addEventListener('input',()=>{if(purpose.value==='Role Requirement'){const summary=modal.querySelector('#f_summary');if(summary&&(!summary.value.trim()||summary.dataset.autoCourseName==='1')){summary.value=modal.querySelector('#f_certificate').value;summary.dataset.autoCourseName='1'}}});sync(false);
  }

  function applyFireChecklistTemplate(modal,resetValues=true){const selected=modal?.querySelector('#f_checklist_template')?.value||'';const template=FIRE_CHECKLIST_TEMPLATES.find(x=>x.id===selected),status=modal?.querySelector('[data-fire-template-status]');modal?.querySelectorAll('[data-fire-check-field]').forEach(el=>{const key=el.dataset.fireCheckField;el.hidden=!!template&&!template.fields.includes(key);const input=el.querySelector('select');if(input&&resetValues&&template?.fields.includes(key))input.value='Select result'});if(template){const freq=modal.querySelector('#f_inspection_frequency'),period=modal.querySelector('#f_checklist_period');if(freq)freq.value=template.frequency;if(period)period.value=template.period;if(status)status.textContent=`${template.fields.length} checklist points selected. Record actual results for all visible points.`}else if(status)status.textContent='Standard register view: all inspection fields are shown.';if(resetValues&&modal?.dataset.localDraftKey)saveLocalDraftSnapshot(modal,modal.dataset.localDraftKey)}

  function permitClassGuideHTML(type){const guide={general_work:['General Work Permit','Routine activities such as housekeeping, cleaning, routine visual inspection and approved low-risk oiling/PPM that do not involve hot work or critical hazards. If isolation, machine guarding access or another critical hazard is involved, reclassify the permit.'],hot_work:['Hot Work Permit','Welding, gas/electric cutting, grinding and other spark/flame/heat-generating tasks. Confirm combustible control, suitable extinguisher, fire watch and post-work fire watch.'],critical_work:['Critical Work Permit','Confined space, work at height, electrical work, lifting, excavation, line breaking, chemical work and energy isolation/LOTO. Select the applicable critical subtype and verify its controls.']};const x=guide[type]||guide.general_work;return `<div class="notice permit-class-guide"><b>${esc(x[0])}</b><p>${esc(x[1])}</p><small>Classification aid only. Follow the company-approved PTW procedure and applicable legal/client requirements.</small></div>`}
  function renderPermitDynamic(modal,data){
    const type=modal.querySelector('#f_permit_type')?.value||'general_work';const holder=modal.querySelector('#permit-dynamic');if(!holder)return;holder.innerHTML=permitClassGuideHTML(type)+permitDynamicHTML(type,data)+(type==='critical_work'?criticalDetailHTML(data.critical_type||'confined_space',data):'');
    if(type==='critical_work'){const ct=modal.querySelector('#f_critical_type');ct?.addEventListener('change',()=>{modal.querySelector('#critical-detail-fields').innerHTML=criticalDetailHTML(ct.value,collectFormData(modal))})}
  }
  function collectFormData(modal){const d={};modal.querySelectorAll('[id^="f_"]').forEach(el=>{const id=el.id.slice(2);if(['event_date','location','department','status','summary','related','file'].includes(id))return;d[id]=el.type==='number'?el.value:el.value});return d}

