      const existingCase=recordId?state.records.find(r=>r.id===recordId):null;if(seriousCaseClosureMissingAction(recordId,existingCase,requestedStatus,get('severity'),get('corrective_action_reference'),state.records)){toast('A major / critical incident or accident cannot be closed until a linked corrective action exists. Save it as Open, create a linked action, then close after review.',false);modal.querySelector('#f_status')?.focus();return}
