        if(!/^[A-Z0-9_-]{2,20}$/.test(prefix)){toast('Prefix must be 2–20 letters, numbers, hyphens or underscores.',false);return;}if(!date){toast('Select a default issue date.',false);return;}if(!format.includes('{PREFIX}')||!format.includes('{CODE}')||!format.includes('{SEQ}')){toast('Number format must include {PREFIX}, {CODE} and {SEQ}.',false);return;}
