  async function saveHseQuickUpdate(id,button){
    const r=state.records.find(x=>x.id===id),wrap=button.closest('.hse-quick-update');if(!r||!wrap)return;
    if(!can(r.module,'edit',r)){toast('You do not have permission to update this record.',false);return}
    const requested=wrap.querySelector('[data-hse-status]')?.value||r.status,remark=wrap.querySelector('[data-hse-remark]')?.value.trim()||'';
    const data={...(r.data||{}),latest_update_remark:remark};
    if(String(r.status).toLowerCase()==='closed'&&requested!=='closed'&&!remark){toast('Enter a reason before reopening this record.',false);return}
    if(requested==='closed'){
      const work=wrap.querySelector('[data-hse-work]')?.value.trim()||'',person=wrap.querySelector('[data-hse-person]')?.value.trim()||'',date=wrap.querySelector('[data-hse-date]')?.value||'',time=wrap.querySelector('[data-hse-time]')?.value||'';
      if(!work||!person||!date||!time||!remark){toast('Complete the work, person, closure date/time and closure remarks.',false);return}
      const effective=`${date}T${time}:00`, effectiveMs=new Date(effective).getTime();if(!Number.isFinite(effectiveMs)||effectiveMs>Date.now()+60000){toast('Enter a valid closure time no later than now.',false);return}
      data.completion_work=work;data.completion_person=person;data.effective_completion_at=new Date(effectiveMs).toISOString();data.closure_remark=remark;data.backdate_reason=effectiveMs<Date.now()-60000?(wrap.querySelector('[data-hse-backdate-reason]')?.value.trim()||''):'';
      if(effectiveMs<Date.now()-60000&&!data.backdate_reason){toast('Explain why this completion is being recorded retrospectively.',false);return}
      if(r.module==='actions'){data.completion_evidence=wrap.querySelector('[data-hse-evidence]')?.value.trim()||'';data.effectiveness_status=wrap.querySelector('[data-hse-effect]')?.value||'Pending verification';data.verifier=wrap.querySelector('[data-hse-verifier]')?.value.trim()||'';data.verified_at=wrap.querySelector('[data-hse-verified]')?.value||'';const issue=actionClosureValidationError({...data,status:'closed'},today());if(issue){toast(issue.message,false);return}}
      const linked=hseLinkedActions(r),open=linked.filter(a=>!['closed','cancelled','void'].includes(String(a.status||'').toLowerCase()));if(r.module!=='actions'&&open.length){toast(`Close the ${open.length} outstanding linked corrective action(s) before closing this case.`,false);return}
      if(['incidents','accidents'].includes(r.module)&&['major','critical'].includes(String(data.severity||'').toLowerCase())&&!linked.length){toast('A major / critical case needs a linked corrective action before closure.',false);return}
    } else if(requested==='in_progress'&&!remark){toast('Add a progress remark before saving.',false);return}
    else if(String(r.status).toLowerCase()==='closed'&&requested!=='closed')data.reopen_reason=remark;
    const summary=r.summary||`${MODULES[r.module]?.singular||'HSE'} record`;
    button.disabled=true;button.textContent='Saving…';
    try{const {error}=await sb.rpc('update_hse_record',{p_org_id:activeOrgId(),p_id:r.id,p_event_date:r.event_date,p_location:r.location||'',p_department:r.department||'',p_status:requested,p_summary:summary,p_data:data,p_attachment:r.attachment||null});if(error)throw error;await loadRecords();renderPage();updateNotificationCount();toast('Status update saved.')}catch(e){button.disabled=false;button.textContent=requested==='closed'?'Save Closure':'Save Update';toast(`Update failed. Your text is still here. ${e?.message||e}`,false)}
  }

