  function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(c==='"'&&quoted&&n==='"'){cell+='"';i++;continue}if(c==='"'){quoted=!quoted;continue}if(c===','&&!quoted){row.push(cell);cell='';continue}if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&n==='\n')i++;row.push(cell);cell='';if(row.some(x=>x.trim()!==''))rows.push(row);row=[];continue}cell+=c}if(quoted)throw new Error('CSV contains an unclosed quoted field. Correct the source file and retry.');if(cell!==''||row.length){row.push(cell);if(row.some(x=>x.trim()!==''))rows.push(row)}return rows}

  async function importCSV(module,file){
    if(!file)return;
    if(!can(module,'create')){toast('CSV import requires create permission for this module.',false);return}
    let rows;
    try{const text=await file.text();rows=parseCSV(text)}catch(e){toast(`Could not read CSV: ${e.message||e}`,false);return}
    if(rows.length<2){toast('CSV contains no data rows.',false);return}
    const headers=rows[0].map(x=>normalizeImportHeader(x));const dataRows=rows.slice(1);const blankDateRows=dataRows.reduce((n,row)=>n+(!String(row[headers.findIndex(h=>['event_date','date','inspection_date','issue_date','joining_date','training_date'].includes(h))]||'').trim()?1:0),0);
    const useTodayForBlankDates=blankDateRows>0?confirm(`${blankDateRows} row(s) have no event date. Choose OK to explicitly use today (${today()}) for those rows, or Cancel to skip them and include them in a downloadable error report.`):false;
    const seen=new Set(),errors=[],imported=[];let ok=0,fail=0,skipped=0;
    for(let i=0;i<dataRows.length;i++){
      const vals=dataRows[i],sourceRow=i+2,raw={};headers.forEach((h,j)=>{raw[h]=String(vals[j]??'').trim()});
      const rawDate=raw.event_date||raw.date||raw.inspection_date||raw.issue_date||raw.joining_date||raw.training_date||'';
      let eventDate=rawDate?normalizeImportDate(rawDate):(useTodayForBlankDates?today():'');
      const reject=(reason)=>{fail++;errors.push({__source_row:sourceRow,__error:reason,...Object.fromEntries(headers.map((h,j)=>[h,String(vals[j]??'')]))})};
      if(rawDate&&!eventDate){reject(`Invalid event date: ${rawDate}. Use YYYY-MM-DD or DD/MM/YYYY.`);continue}
      if(!eventDate){reject('Event date is blank; row skipped because today-date fallback was not approved.');continue}
      const location=raw.location||raw.equipment_location||raw.area||raw.work_location||'';
      const department=raw.department||raw.department_name||state.membership?.department||state.profile?.department||'';
      const status=module==='permits'?'draft':(raw.status||raw.renewal_status||raw.inspection_status||'open').toLowerCase().replace(/[\s-]+/g,'_');
      const summary=raw.summary||raw.description||raw.document_name||raw.employee_name||raw.equipment_id||raw.ppe_item||raw.equipment_type||raw.chemical_name||`${MODULES[module]?.singular||module} record`;
      const d={...raw,import_source:file.name,import_source_row:sourceRow};['event_date','date','inspection_date','issue_date','joining_date','training_date','location','equipment_location','area','work_location','department','department_name','status','summary','description'].forEach(k=>delete d[k]);
      if(module==='waste'){const blockers=wasteMovementBlockingIssues(d,today(),status==='draft');if(blockers.length){reject(`Waste traceability incomplete: ${blockers.join('; ')}`);continue}}
      const model={event_date:eventDate,location,summary};if(importDuplicate(model,module,seen)){skipped++;continue}
      try{
        const {error}=await sb.rpc('create_hse_record',{p_org_id:activeOrgId(),p_module:module,p_event_date:eventDate,p_location:location,p_department:department,p_status:status,p_summary:summary,p_data:d,p_attachment:null});
        if(error){reject(error.message||'Database rejected this row.');continue}
        ok++;imported.push({sourceRow,eventDate,summary});
      }catch(e){reject(e?.message||'Network error while saving this row.')}
    }
    if(errors.length){const allKeys=[...new Set([...headers,'__source_row','__error'])];const csv=[allKeys.map(csvCell).join(','),...errors.map(row=>allKeys.map(k=>csvCell(row[k]??'')).join(','))].join('\n');download(csv,`${module}-import-errors-${today()}.csv`,'text/csv;charset=utf-8')}
    try{await loadRecords();renderPage();updateNotificationCount()}catch(e){toast(`Import completed but records could not be refreshed. Reload the register to verify saved rows. ${e?.message||e}`,false);return}
    toast(`CSV import complete: ${ok} imported, ${skipped} duplicate(s) skipped, ${fail} row(s) need correction.${errors.length?' Downloaded the row-level error CSV.':''}`,fail===0);
  }

  function exportTrainingRequirementMatrix(){
    const data=trainingRequirementMatrixRows();const rows=[];
    data.employees.forEach(employee=>employee.items.forEach(item=>rows.push({employee_code:employee.code,employee_name:employee.name,designation:employee.designation,department:employee.department,employment_type:employee.employmentType,course_code:item.courseCode,course_name:item.courseName,requirement_strength:item.strength,status:item.status,expiry_date:item.expiry,expiry_derived:item.expiryDerived?'Yes':'No',matched_evidence_count:item.matchedEvidenceCount,evidence_reference:item.evidence?.reference_no||item.evidence?.data?.proof_reference||'',evidence_record_id:item.evidence?.id||'',requirement_reference:item.requirement?.reference_no||'',requirement_record_id:item.requirement?.id||'',review_note:item.status==='missing'?'No exact employee-code + course-code evidence found':item.status==='expiry_unverified'?'Evidence found but expiry cannot be verified':item.status==='employee_code_missing'?'Employee code required for exact matrix matching':item.status==='due_30'?'Renewal due within 30 days':''})));
    data.configurationGaps.forEach(g=>rows.push({course_code:g.requirement.data?.course_code||'',course_name:g.requirement.data?.certificate||g.requirement.summary||'',requirement_strength:g.requirement.data?.requirement_strength||'',status:'Configuration gap',requirement_reference:g.requirement.reference_no||'',requirement_record_id:g.requirement.id||'',review_note:g.missing.join('; ')}));
    const keys=['employee_code','employee_name','designation','department','employment_type','course_code','course_name','requirement_strength','status','expiry_date','expiry_derived','matched_evidence_count','evidence_reference','evidence_record_id','requirement_reference','requirement_record_id','review_note'];const csv=[keys.join(','),...rows.map(r=>keys.map(k=>csvCell(r[k])).join(','))].join('\n');download(csv,`${state.activeOrg?.slug||'hse360'}-role-training-requirement-matrix-${today()}.csv`,'text/csv;charset=utf-8');toast(`Role training matrix exported (${data.employees.length} employees, ${rows.length} checks/configuration rows, ${data.configurationGaps.length} requirement configuration gap(s)).`)
  }

